import{_ as a,c as t,o as i,aj as r}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse('{"title":"Cold Iron Cloud Pan Pizza","description":"High-hydration cold-fermented pan pizza for cast iron or enameled pans, with a crisp bottom and cloud-soft crumb.","frontmatter":{"title":"Cold Iron Cloud Pan Pizza","description":"High-hydration cold-fermented pan pizza for cast iron or enameled pans, with a crisp bottom and cloud-soft crumb.","head":[["meta",{"name":"description","content":"High-hydration cold-fermented pan pizza for cast iron or enameled pans, with a crisp bottom and cloud-soft crumb."}],["meta",{"property":"og:title","content":"Cold Iron Cloud Pan Pizza"}],["meta",{"property":"og:description","content":"High-hydration cold-fermented pan pizza for cast iron or enameled pans, with a crisp bottom and cloud-soft crumb."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/cold-iron-cloud-pan-pizza.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Cold Iron Cloud Pan Pizza"}],["meta",{"name":"twitter:description","content":"High-hydration cold-fermented pan pizza for cast iron or enameled pans, with a crisp bottom and cloud-soft crumb."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/cold-iron-cloud-pan-pizza.html"}]]},"headers":[],"relativePath":"recipes/cold-iron-cloud-pan-pizza.md","filePath":"recipes/cold-iron-cloud-pan-pizza.md"}'),l={name:"recipes/cold-iron-cloud-pan-pizza.md"};function o(n,e,s,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="cold-iron-cloud-pan-pizza" tabindex="-1">Cold Iron Cloud Pan Pizza <a class="header-anchor" href="#cold-iron-cloud-pan-pizza" aria-label="Permalink to “Cold Iron Cloud Pan Pizza”">​</a></h1><p>This is high-hydration dough with a safety net: thermal mass, oil, and time. The pan does the heavy lifting while the dough does what wet dough does best: retain gas and stay tender. You get a crisp, fried bottom and a moist, airy crumb without pretending this is hand-tossed pizza. Use the <a href="https://calculator.kitchenratio.com" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch size.</p><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example batch)”">​</a></h2><p>Example shown is sized for a ~13-inch enameled braiser.</p><ul><li><strong>Flour</strong> - 300g (100%)</li><li><strong>Water</strong> - 234g (78%)</li><li><strong>Salt</strong> - 6g (2%)</li><li><strong>Dry yeast</strong> - 2-2.4g (0.7-0.8%)</li><li><strong>Olive oil</strong> - 18g (6%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><div class="info custom-block"><p class="custom-block-title">Note</p><ul><li>Dough will be very loose. This is intentional.</li><li>If it feels too wet, resist the urge to add flour and trust the folds.</li><li>Oil the pan generously.</li><li>Best baked from a cold pan start.</li></ul></div><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-mix" tabindex="-1">1. Mix <a class="header-anchor" href="#_1-mix" aria-label="Permalink to “1. Mix”">​</a></h3><ul><li>Combine water, yeast, salt, oil, and flour.</li><li>Mix until no dry flour remains.</li><li>Dough should look shaggy and loose.</li><li>Do not knead.</li><li>Rest 10 minutes.</li></ul><h3 id="_2-build-structure-coil-folds" tabindex="-1">2. Build Structure (Coil Folds) <a class="header-anchor" href="#_2-build-structure-coil-folds" aria-label="Permalink to “2. Build Structure (Coil Folds)”">​</a></h3><ul><li>With wet hands, perform one fold, then rest 5 minutes.</li><li>Repeat for 4 total folds.</li><li>By the last fold, dough should feel smoother, more elastic, and still very soft.</li><li>Think of folds as structured gluten alignment, not brute-force kneading.</li></ul><h3 id="_3-pre-fridge-rest-cold-ferment" tabindex="-1">3. Pre-Fridge Rest + Cold Ferment <a class="header-anchor" href="#_3-pre-fridge-rest-cold-ferment" aria-label="Permalink to “3. Pre-Fridge Rest + Cold Ferment”">​</a></h3><ul><li>Cover and rest 30-40 minutes at room temperature.</li><li>Refrigerate 24-72 hours.</li><li>Longer cold time builds deeper flavor and better extensibility.</li><li>Cold time also softens yeast harshness and makes this dough easier to open in the pan.</li></ul><h3 id="_4-pan-final-proof" tabindex="-1">4. Pan + Final Proof <a class="header-anchor" href="#_4-pan-final-proof" aria-label="Permalink to “4. Pan + Final Proof”">​</a></h3><ul><li>Generously oil your enameled cast-iron braiser or heavy pan.</li><li>Scrape cold dough directly into the pan.</li><li>Stretch and dimple with oiled fingers.</li><li>If it resists, wait 5 minutes and continue gently.</li><li>Cover and proof 2-3 hours until puffy, jiggly, and visibly bubbled.</li></ul><p>Need a brasier? <a href="https://amzn.to/3MCdJOS" target="_blank" rel="noreferrer">Tramontina Bestow Enameled Cast Iron Braiser Pan with Lid, 4-Quart</a>.</p><h3 id="_5-topping" tabindex="-1">5. Topping <a class="header-anchor" href="#_5-topping" aria-label="Permalink to “5. Topping”">​</a></h3><ul><li>Top gently to preserve gas: <ul><li>Most of the cheese</li><li>Sauce (light hand, do not flood it)</li><li>Other toppings</li><li>Remaining cheese</li></ul></li></ul><h3 id="_6-bake-cold-pan-start" tabindex="-1">6. Bake (Cold Pan Start) <a class="header-anchor" href="#_6-bake-cold-pan-start" aria-label="Permalink to “6. Bake (Cold Pan Start)”">​</a></h3><ul><li>Oven: <strong>450-465F (230-240C)</strong></li><li>Rack: lower third</li><li>Bake with the lid <strong>off</strong>.</li><li>Bake 25-35 minutes, rotating once if needed.</li><li>Bottom should finish deeply golden and crisp.</li><li>If the top finishes early, place the room-temperature lid on to slow top browning (or tent loosely with foil).</li></ul><h2 id="pan-size-and-bake-time-starting-guide" tabindex="-1">Pan Size and Bake Time (Starting Guide) <a class="header-anchor" href="#pan-size-and-bake-time-starting-guide" aria-label="Permalink to “Pan Size and Bake Time (Starting Guide)”">​</a></h2><p>Use this as your first pass, then adjust by color and bottom crispness.</p><table tabindex="0"><thead><tr><th>Pan size</th><th>Dough feel in pan</th><th>Typical bake time at 450-465F</th></tr></thead><tbody><tr><td>10-inch</td><td>Thicker, more focaccia-like</td><td>30-38 minutes</td></tr><tr><td>12-inch</td><td>Balanced thickness</td><td>27-34 minutes</td></tr><tr><td>13-inch</td><td>Target profile for this formula</td><td>25-35 minutes</td></tr><tr><td>14-inch</td><td>Thinner, crisper profile</td><td>22-30 minutes</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Heavy enameled cast iron can run slower than dark steel pans. Trust bottom color and edge set more than the timer.</p></div><h3 id="_7-rest" tabindex="-1">7. Rest <a class="header-anchor" href="#_7-rest" aria-label="Permalink to “7. Rest”">​</a></h3><ul><li>Rest 10-15 minutes before removing from the pan.</li><li>This sets the crumb, prevents collapse, and gives cleaner slices.</li></ul><h2 id="texture-and-flavor-profile" tabindex="-1">Texture and Flavor Profile <a class="header-anchor" href="#texture-and-flavor-profile" aria-label="Permalink to “Texture and Flavor Profile”">​</a></h2><ul><li><strong>Bottom</strong>: crisp, pan-fried, nearly shattery.</li><li><strong>Crumb</strong>: open, moist, cloud-soft.</li><li><strong>Flavor</strong>: light tang, olive-oil richness, no yeast harshness.</li></ul><h2 id="plain-truth" tabindex="-1">Plain Truth <a class="header-anchor" href="#plain-truth" aria-label="Permalink to “Plain Truth”">​</a></h2><p>This is not a pizza hack. It is a technique-driven pan pie that happens to be forgiving and fun. High hydration is not the gimmick here; process control is.</p><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/cold-fermentation.html">Cold Fermentation</a></li><li><a href="/guides/folding.html">Folding</a></li></ul><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul><h2 id="related-recipes" tabindex="-1">Related Recipes <a class="header-anchor" href="#related-recipes" aria-label="Permalink to “Related Recipes”">​</a></h2><ul><li><a href="/recipes/colorado-pizza-dough.html">Colorado Style Pizza Dough</a></li></ul><blockquote><p><strong>Affiliate Disclaimer</strong> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',39)])])}const m=a(l,[["render",o]]);export{u as __pageData,m as default};
